-- Synthetic schema ONLY for crm-integration.mysql.test.cjs, not a tenant migration.
CREATE TABLE parametros(CODIGO INT PRIMARY KEY,VALIDA_CPF_CNPJ VARCHAR(3),CODIGO_ERP VARCHAR(3)) ENGINE=InnoDB;
CREATE TABLE operadores(CODIGO INT PRIMARY KEY,NOME VARCHAR(50),ATIVO VARCHAR(3),NIVEL VARCHAR(12),SETOR INT) ENGINE=InnoDB;
CREATE TABLE clientes(CODIGO INT NOT NULL AUTO_INCREMENT PRIMARY KEY,RAZAO VARCHAR(100),CPF_CNPJ VARCHAR(20),COD_CAMPANHA INT DEFAULT 3,OPERADOR INT DEFAULT 10,SETOR INT DEFAULT 2,AREA1 INT,FONE1 VARCHAR(9),AREA2 INT,FONE2 VARCHAR(9),AREA3 INT,FONE3 VARCHAR(9),AREAFAX INT,FAX VARCHAR(9)) ENGINE=InnoDB;
CREATE TABLE fones_campanha_cli(CODIGO INT NOT NULL AUTO_INCREMENT PRIMARY KEY,CLIENTE INT NOT NULL,FONE VARCHAR(20) NOT NULL,TIPO_FONE VARCHAR(15) NULL,UNIQUE KEY customer_phone(CLIENTE,FONE)) ENGINE=InnoDB;
CREATE TABLE campanhas(CODIGO INT PRIMARY KEY,NOME VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE campanhas_clientes(CODIGO INT PRIMARY KEY,CLIENTE INT,CAMPANHA INT,OPERADOR INT,CONCLUIDO ENUM('SIM','NAO'),FIDELIZA VARCHAR(1),DT_AGENDAMENTO DATETIME NULL,DATA_HORA_LIG DATETIME NULL,DATA_HORA_FIM DATETIME NULL,RESULTADO INT,KEY customer_id(CLIENTE)) ENGINE=InnoDB;
CREATE TABLE fidelizacoes(CODIGO INT PRIMARY KEY,CLIENTE INT,OPERADOR_CRIACAO INT,CC_CODIGO INT,QTDE_FIDELIZAR INT,KEY customer_id(CLIENTE)) ENGINE=InnoDB;
CREATE TABLE transferencia_clientes(CODIGO INT NOT NULL AUTO_INCREMENT PRIMARY KEY,DATA_HORA DATETIME,OPERADOR INT,OPERADOR_ORIGEM INT,OPERADOR_DESTINO INT) ENGINE=InnoDB;
CREATE TABLE transferencia_clientes_itens(CODIGO INT,CLIENTE INT,PRIMARY KEY(CODIGO,CLIENTE)) ENGINE=InnoDB;
CREATE TABLE historico_cli(CODIGO INT NOT NULL AUTO_INCREMENT PRIMARY KEY,CLIENTE INT,CC_CODIGO INT,TELEFONE VARCHAR(20)) ENGINE=InnoDB;
CREATE TABLE resultados(CODIGO INT PRIMARY KEY,COD_ACAO INT,PROPOSTA VARCHAR(1),CANCELAPROPOSTA VARCHAR(1),PESQUISA_SATISFACAO VARCHAR(1)) ENGINE=InnoDB;
CREATE TABLE telephony_schedule_finishes(operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,request_hash CHAR(64) NOT NULL,schedule_id INT NOT NULL,actor_id INT NOT NULL,created_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE pesquisa_satisfacao(PESQSAT_CODIGO INT NOT NULL AUTO_INCREMENT PRIMARY KEY,PESQ_DESCRICAO VARCHAR(1000) NOT NULL) ENGINE=InnoDB;
CREATE TABLE pesquisa_satisfacao_avaliacao(CAMPCLI_CODIGO INT NOT NULL,PESQSAT_CODIGO INT NOT NULL,PESQSAT_AVALIACAO ENUM('','1','2','3','4','5') NULL,PRIMARY KEY(CAMPCLI_CODIGO,PESQSAT_CODIGO)) ENGINE=InnoDB;
CREATE TABLE telephony_satisfaction_submissions(operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,schedule_id INT NOT NULL,actor_id INT NOT NULL,history_id INT NOT NULL,survey_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY history_id(history_id)) ENGINE=InnoDB;
CREATE TABLE propostas(CODIGO INT NOT NULL AUTO_INCREMENT PRIMARY KEY,LIGACAO INT,VALOR DOUBLE,SITUACAO ENUM('CANCELADA','ATIVA') DEFAULT 'ATIVA',KEY schedule_id(LIGACAO)) ENGINE=InnoDB;
CREATE TABLE propostas_compras(PROPOSTA INT NOT NULL,COMPRA INT NOT NULL,PRIMARY KEY(PROPOSTA,COMPRA)) ENGINE=InnoDB;
CREATE TABLE crm_proposal_events(operation_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,proposal_id INT NOT NULL,schedule_id INT NOT NULL,actor_id INT NOT NULL,action VARCHAR(16) NOT NULL,old_value VARCHAR(64),new_value VARCHAR(64),old_status VARCHAR(32),new_status VARCHAR(32),customer_id INT NOT NULL,campaign_id INT,reason VARCHAR(250) NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(operation_id,proposal_id),KEY proposal_history(proposal_id,created_at)) ENGINE=InnoDB;
